DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT104-S4-Q13$pilot$ AND c.letter=$pilot$A$pilot$ AND c.choice_text=$pilot$There is no point in trying to find someone else to solve that problem. If Robin cannot solve it, then none of Robin’s friends would be able to solve it.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT104-S4-Q13 A'; END IF; END $guard$;
