DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$pilot$PT104-S4-Q13$pilot$ AND c.letter=$pilot$D$pilot$ AND c.choice_text=$pilot$There is no point in asking the club to purchase tents and make them available for use by club members. No member of the club can afford one of those tents, so the club is unable to afford any either.$pilot$) THEN RAISE EXCEPTION 'Choice changed: PT104-S4-Q13 D'; END IF; END $guard$;
